const frTaskQBank = {
A1:[
[{q:"What does 'Bonjour' mean?",opts:["Good evening","Good night","Hello / Good day","Goodbye"],a:2,ex:"'Bonjour' (literally 'good day') is the standard greeting from morning until evening."},{q:"Which greeting specifically means 'good evening'?",opts:["Bonjour","Salut","Bonsoir","Au revoir"],a:2,ex:"'Bonsoir' = good evening; it replaces 'bonjour' from late afternoon on. 'Salut' is just 'hi'."},{q:"'Enchanté(e)' means:",opts:["Thank you very much","Nice to meet you","Excuse me, please","See you soon"],a:1,ex:"'Enchanté(e)' is said when you meet someone for the first time; add -e if you are a woman."},{q:"'Salut' is used in ___ situations.",opts:["formal","informal","written","official"],a:1,ex:"'Salut' (hi/bye) is for friends and family; use 'bonjour' with strangers or at work."},{q:"'Comment vous appelez-vous ?' asks:",opts:["How are you?","What is your name?","Where do you live?","How old are you?"],a:1,ex:"'S'appeler' = to be called, so it literally asks 'how do you call yourself?'"},{q:"It is 9 pm and you arrive at a party. You say:",opts:["Bonjour","Bonne nuit","Bonsoir","Bon matin"],a:2,ex:"'Bonne nuit' is only said when going to bed; on arrival in the evening you say 'bonsoir'."}],
[{q:"Which accent is on the 'e' in 'été' (summer), giving the closed 'ay' sound?",opts:["grave (è)","acute (é)","circumflex (ê)","diaeresis (ë)"],a:1,ex:"The accent aigu (é) marks the closed [e] sound, as in 'café' and 'été'."},{q:"The letter 'c' before 'e' or 'i' sounds like:",opts:["k","g","s","zh"],a:2,ex:"Before e, i or y, 'c' is soft [s] (ceci, cinéma); before a, o, u it is hard [k]."},{q:"'La liaison' in French means:",opts:["dropping the final -e of a word","linking a final consonant to a next vowel","a silent letter at the end of a word","a mark placed over a vowel"],a:1,ex:"In 'les amis' the normally silent s is pronounced [z] and joined to the vowel: les‿amis."},{q:"The cedilla in 'ç' (as in 'garçon') makes the 'c' sound like:",opts:["k","s","sh","g"],a:1,ex:"'Ç' keeps the c soft [s] before a, o, u: ça, garçon, reçu."},{q:"Final consonants in French are usually:",opts:["stressed","silent","doubled","rolled"],a:1,ex:"Most final consonants are silent (petit, grand); c, r, f and l are common exceptions."},{q:"In 'à huit heures' (at eight o'clock), which accent does 'à' take?",opts:["acute (á)","grave (à)","circumflex (â)","no accent (a)"],a:1,ex:"The preposition 'à' takes a grave accent, which distinguishes it from 'a' (has, from avoir)."}],
[{q:"What is 'vingt' in English?",opts:["12","20","22","80"],a:1,ex:"'Vingt' is 20; vingt-deux is 22 and quatre-vingts is 80."},{q:"How do you say 70 in France?",opts:["septante","soixante-dix","sept-dizaines","soixante-sept"],a:1,ex:"France counts 70 as 60 + 10 (soixante-dix); 'septante' is Belgian and Swiss usage."},{q:"In France, which word means 80?",opts:["huitante","quatre-vingts","octante","huit-vingts"],a:1,ex:"80 is 4 × 20 = quatre-vingts in France; 'huitante' is only used in parts of Switzerland."},{q:"'Cent' means:",opts:["10","100","1000","11"],a:1,ex:"'Cent' = 100; 'dix' = 10, 'onze' = 11 and 'mille' = 1000."},{q:"'Quinze' is:",opts:["5","50","15","55"],a:2,ex:"'Quinze' = 15; don't confuse it with 'cinq' (5) or 'cinquante' (50)."},{q:"'Il est sept heures et demie' =",opts:["7:15","6:30","7:30","7:45"],a:2,ex:"'Et demie' adds half an hour; 'et quart' would be 7:15 and 'moins le quart' 6:45."}],
[{q:"Which article goes with 'table' (feminine)?",opts:["le","la","les","un"],a:1,ex:"'La' is the definite article for feminine singular nouns: la table, la porte."},{q:"Which article goes with 'livre' (book, masculine)?",opts:["le","la","les","une"],a:0,ex:"'Le' is the masculine singular definite article; 'une' is feminine and indefinite."},{q:"The plural definite article for both genders is:",opts:["le","la","des","les"],a:3,ex:"'Les' is used for all plural nouns: les livres, les tables."},{q:"Indefinite article for a feminine noun:",opts:["un","une","des","le"],a:1,ex:"'Une' = a/an with feminine nouns (une table); 'un' is masculine and 'des' is plural."},{q:"Before a vowel, 'le' / 'la' become:",opts:["les","l'","un","de"],a:1,ex:"'Le' and 'la' elide to l' before a vowel or mute h: l'ami, l'école, l'hôtel."},{q:"Days of the week are:",opts:["feminine (la lundi)","masculine (le lundi)","neuter (no article)","plural only (les lundi)"],a:1,ex:"All days of the week are masculine: le lundi, un dimanche."}],
[{q:"Correct form: 'Tu ___ en France.'",opts:["habite","habites","habitez","habitons"],a:1,ex:"Regular -er verbs take -es with 'tu': tu habites, tu parles."},{q:"Which ending goes with 'nous' for -er verbs?",opts:["-e","-es","-ons","-ez"],a:2,ex:"-er verbs: je -e, tu -es, il -e, nous -ons, vous -ez, ils -ent."},{q:"Conjugate 'avoir' for 'elle':",opts:["ai","as","a","avons"],a:2,ex:"'Avoir': j'ai, tu as, il/elle a, nous avons, vous avez, ils ont."},{q:"'Je ___' (être):",opts:["es","suis","est","sommes"],a:1,ex:"'Être' is irregular: je suis, tu es, il est, nous sommes."},{q:"'Vous ___ français.' (parler)",opts:["parlez","parles","parle","parlent"],a:0,ex:"With 'vous', -er verbs end in -ez: vous parlez."},{q:"'Tu ___ couches à quelle heure ?'",opts:["te","se","me","vous"],a:0,ex:"The reflexive pronoun matches the subject: je me, tu te, il se, so 'tu te couches'."}],
[{q:"How do you politely order in a café?",opts:["Je voudrais un café, s'il vous plaît.","Donne-moi un café, vite, garçon !","Je veux un café, et maintenant.","Apporte-moi un café, toi."],a:0,ex:"The conditional 'je voudrais' plus 's'il vous plaît' is the standard polite way to order."},{q:"'L'addition, s'il vous plaît' means:",opts:["The menu, please","Can I order?","The bill, please","Excuse me"],a:2,ex:"In a restaurant 'l'addition' is the bill; 'la carte' is the menu."},{q:"'Qu'est-ce que vous recommandez ?' means:",opts:["What is the special?","What do you recommend?","Do you have a table?","Is service included?"],a:1,ex:"'Recommander' = to recommend; you are asking the waiter for advice."},{q:"'La carte' (in a restaurant) is the:",opts:["bill","menu","waiter","kitchen"],a:1,ex:"'La carte' is the menu; 'le menu' often means a set meal at a fixed price."},{q:"'Bon appétit !' means:",opts:["Cheers!","Enjoy your meal!","The bill, please!","Welcome!"],a:1,ex:"'Bon appétit !' is said before eating; 'Santé !' is the toast for 'Cheers!'."},{q:"'Le déjeuner' is usually eaten:",opts:["in the morning","late at night","at midday","at 5 pm"],a:2,ex:"In France 'le déjeuner' is lunch; breakfast is 'le petit-déjeuner' and dinner 'le dîner'."}],
[{q:"'La sœur' means:",opts:["brother","mother","sister","aunt"],a:2,ex:"'La sœur' = sister; 'le frère' = brother, 'la mère' = mother, 'la tante' = aunt."},{q:"'Le grand-père' means:",opts:["uncle","grandfather","father","stepfather"],a:1,ex:"'Grand-' + family word gives grandparents: grand-père, grand-mère."},{q:"French for a female cousin?",opts:["la cousine","la sœur","la nièce","la tante"],a:0,ex:"Add -e for the female form: le cousin → la cousine."},{q:"'Les parents' usually means:",opts:["the children","the parents","the grandparents","the cousins"],a:1,ex:"'Les parents' normally means mother and father (it can also mean relatives in general)."},{q:"'Le fils' means:",opts:["son","daughter","nephew","brother"],a:0,ex:"'Le fils' (pronounced 'fiss') is son; 'la fille' is daughter."},{q:"'Le dimanche, je mange chez mes grands-parents' means:",opts:["This Sunday I eat at my grandparents'","On Sundays I eat at my grandparents'","Last Sunday I ate at my parents'","On Sunday my grandparents eat at my house"],a:1,ex:"'Le' + day expresses a habit (every Sunday); 'dimanche' alone would mean this Sunday."}],
[{q:"'Se lever' means:",opts:["to eat","to sleep","to get up","to go out"],a:2,ex:"'Se lever' = to get up (out of bed); 'se réveiller' = to wake up."},{q:"'Prendre le petit-déjeuner' means:",opts:["to take a shower","to have breakfast","to make lunch","to buy bread"],a:1,ex:"'Prendre' is used for meals and drinks: prendre le petit-déjeuner, prendre un café."},{q:"'S'endormir' means:",opts:["to wake up","to dream","to fall asleep","to rest"],a:2,ex:"'S'endormir' = to fall asleep; 'dormir' = to sleep, 'rêver' = to dream."},{q:"'Travailler' means:",opts:["to play","to work","to wait","to walk"],a:1,ex:"'Travailler' = to work; 'jouer' = to play, 'attendre' = to wait, 'marcher' = to walk."},{q:"'Rentrer à la maison' means:",opts:["to go shopping","to go home","to go out","to go to work"],a:1,ex:"'Rentrer' means to come or go back, usually home."},{q:"'Se coucher' means:",opts:["to go to bed","to get dressed","to wake up","to get up"],a:0,ex:"'Se coucher' = to go to bed; 's'habiller' = to get dressed, 'se lever' = to get up."}],
[{q:"'Où habitez-vous ?' asks about:",opts:["your name","where you live","your age","what you do"],a:1,ex:"'Où' (with accent) means where, and 'habiter' = to live."},{q:"Which word asks 'why'?",opts:["comment","quoi","pourquoi","quand"],a:2,ex:"'Pourquoi' = why; 'qui' = who, 'quoi' = what, 'quand' = when."},{q:"'Combien ça coûte ?' means:",opts:["What time is it?","How much does it cost?","Where is it?","Is it open?"],a:1,ex:"'Combien' = how much/many and 'coûter' = to cost."},{q:"'Qui est-ce ?' asks:",opts:["What is that?","Where is that?","Who is it?","When is it?"],a:2,ex:"'Qui' asks about a person; 'Qu'est-ce que c'est ?' asks what something is."},{q:"To ask someone's name formally:",opts:["Comment tu t'appelles ?","Comment vous appelez-vous ?","Qui es-tu ?","Que fais-tu ?"],a:1,ex:"Formal questions use 'vous', often with inversion: Comment vous appelez-vous ?"},{q:"'Quel jour sommes-nous ?' asks:",opts:["What day is it?","What time is it?","Where are we?","How are we?"],a:0,ex:"'Quel jour' = which day; the answer is e.g. 'Nous sommes lundi.'"}],
[{q:"After 'Comment allez-vous ?' a polite response is:",opts:["Très bien, merci. Et vous ?","Je m'appelle Marie, et vous ?","Je vais à la gare, merci.","Oui, s'il vous plaît."],a:0,ex:"'Comment allez-vous ?' asks how you are: give your state and politely return the question."},{q:"'Pouvez-vous répéter, s'il vous plaît ?' means:",opts:["Can you help me?","Can you repeat that, please?","Can you speak more slowly?","Where is the exit?"],a:1,ex:"'Répéter' = to repeat; 'parler plus lentement' would mean to speak more slowly."},{q:"Which farewell is most formal?",opts:["Salut","Ciao","Au revoir","À plus !"],a:2,ex:"'Au revoir' suits any situation; 'salut', 'ciao' and 'à plus' are casual."},{q:"'Excusez-moi, où est... ?' begins a:",opts:["complaint about service","polite request for directions","greeting to a friend","goodbye to a colleague"],a:1,ex:"'Excusez-moi' politely gets attention and 'où est... ?' asks where something is."},{q:"'À demain !' means:",opts:["See you tomorrow!","Good morning!","See you later!","See you next week!"],a:0,ex:"'À' + time word = see you then: à demain (tomorrow), à bientôt (soon), à lundi."},{q:"'Tu viens à quelle heure ?' – Best reply:",opts:["Je viens de Paris.","Vers huit heures.","Oui, merci.","Je m'appelle Paul."],a:1,ex:"'À quelle heure' asks for a time, so answer with one; 'vers' = around."}]
],
A2:[
[{q:"Which auxiliary does 'aller' take in the passé composé?",opts:["avoir","être","faire","aller"],a:1,ex:"'Aller' is a verb of movement that takes être: je suis allé(e)."},{q:"Correct passé composé of 'manger' (je):",opts:["j'ai mangé","j'ai mangi","je suis mangé","j'ai mangés"],a:0,ex:"-er verbs form the past participle in -é and take avoir: j'ai mangé."},{q:"'Hier, je ___ au cinéma.'",opts:["suis allé","ai allé","vais","irai"],a:0,ex:"'Hier' needs a past tense, and aller uses être: je suis allé(e)."},{q:"Past participle of 'finir':",opts:["fini","finu","finit","finé"],a:0,ex:"Regular -ir verbs form the participle in -i: j'ai fini."},{q:"'J'ai ___ le français.' (étudier)",opts:["étudié","étudier","étudiais","étudions"],a:0,ex:"After the auxiliary 'ai' you need the past participle (étudié), not the infinitive."},{q:"'Hier, j'___ mal au dos.' (passé composé)",opts:["ai eu","suis eu","aurai","aurais eu"],a:0,ex:"'Avoir mal' uses avoir, and the participle of avoir is 'eu': j'ai eu mal."}],
[{q:"'Tout droit' means:",opts:["turn left","straight ahead","turn right","go back"],a:1,ex:"'Tout droit' = straight ahead; 'à droite' = to the right. Don't mix them up."},{q:"'Prenez la première rue à gauche' means:",opts:["take the second street on the right","take the first street on the left","go straight past the first street","take the first street on the right"],a:1,ex:"'Première' = first and 'à gauche' = on the left."},{q:"'Comment est-ce que je peux aller à la gare ?' means:",opts:["Is the station far?","How do I get to the station?","Where is the bus stop?","How long does it take?"],a:1,ex:"'Comment aller à...' asks how to get somewhere; 'la gare' is the train station."},{q:"'Tournez à droite' means:",opts:["turn left","turn right","go straight","stop"],a:1,ex:"'Droite' = right and 'gauche' = left; 'tournez' is the vous imperative of tourner."},{q:"'En face de' means:",opts:["next to","opposite","behind","far from"],a:1,ex:"'En face de' = opposite/facing; 'à côté de' = next to, 'derrière' = behind."},{q:"'La pharmacie est plus près que l'hôpital' means the pharmacy is:",opts:["farther than the hospital","as far as the hospital","closer than the hospital","inside the hospital"],a:2,ex:"'Plus près que' = closer than; 'plus loin que' would be farther than."}],
[{q:"'C'est trop cher pour moi' means:",opts:["I'll take it","That's too expensive for me","Do you have another size?","It fits perfectly"],a:1,ex:"'Trop' = too (much) and 'cher' = expensive."},{q:"'Vous l'avez en taille M ?' means:",opts:["Do you have the receipt?","Where is the changing room?","Do you have this in size M?","Can I pay by card?"],a:2,ex:"'La taille' is clothing size, and 'vous l'avez' = do you have it."},{q:"'Je regarde seulement' means:",opts:["I'll buy two","I'm just looking","Can you help me?","I'd like to return this"],a:1,ex:"When asked 'Je peux vous aider ?', 'je regarde seulement' politely declines help."},{q:"'En solde' means:",opts:["sold out","on sale","too expensive","second-hand"],a:1,ex:"'En solde' = reduced in price; 'épuisé' would mean sold out (a false-friend trap)."},{q:"'Je peux payer par carte ?' asks about:",opts:["cash only","paying by card","a discount","the receipt"],a:1,ex:"'Payer par carte' = to pay by card; 'en espèces' = in cash."},{q:"'Ce pull est ___ cher que l'autre.' (less expensive)",opts:["plus","moins","aussi","meilleur"],a:1,ex:"'Moins... que' = less... than; 'plus' = more and 'aussi' = as."}],
[{q:"Which verb is reflexive?",opts:["manger","dormir","se lever","venir"],a:2,ex:"Reflexive verbs come with a pronoun (se) that refers back to the subject."},{q:"Correct form: 'Elle ___ tous les matins.' (se réveiller)",opts:["se réveille","réveille","se réveillez","réveillez"],a:0,ex:"'Elle' takes the pronoun 'se' and the ending -e: elle se réveille."},{q:"In a statement, where does the reflexive pronoun go?",opts:["after the verb","directly before the verb","at the end of the sentence","before the subject"],a:1,ex:"The pronoun sits right before the verb (je me lave); only affirmative commands put it after."},{q:"In the passé composé, reflexive verbs use:",opts:["avoir","être","faire","aller"],a:1,ex:"All reflexive verbs take être in the passé composé: elle s'est levée."},{q:"'Se laver' means:",opts:["to wash oneself","to wake oneself","to dress oneself","to sit down"],a:0,ex:"'Laver' = to wash; with 'se' the action is done to oneself."},{q:"'Je me suis cassé ___ bras.'",opts:["mon","ma","le","au"],a:2,ex:"With body parts, reflexive verbs use the definite article: je me suis cassé le bras."}],
[{q:"In 'Je dois partir maintenant', what form does 'partir' take after 'dois'?",opts:["the infinitive","the past participle","the present tense","the imperative"],a:0,ex:"Modal verbs (devoir, pouvoir, vouloir) are followed directly by an infinitive."},{q:"'Je ___ venir demain, je suis libre.' (I can)",opts:["peux","sais","dois","veux"],a:0,ex:"'Pouvoir' expresses being able / possibility; 'savoir' + infinitive is a learned skill."},{q:"'Tu ___ nager ?' – 'Oui, j'ai appris à six ans.'",opts:["sais","dois","veux","vas"],a:0,ex:"'Savoir' + infinitive refers to a skill you have learned, like swimming."},{q:"'Il faut' + infinitive expresses:",opts:["ability","necessity","permission","desire"],a:1,ex:"'Il faut' + infinitive = it is necessary / one must: il faut partir."},{q:"'Je ___ un café.' (want)",opts:["veux","dois","peux","sais"],a:0,ex:"'Vouloir' = to want: je veux; 'je voudrais' is the more polite form."},{q:"'Vous devriez vous reposer' gives:",opts:["advice","an order in the past","a ban","a comparison"],a:0,ex:"The conditional of devoir (vous devriez = you should) turns obligation into advice."}],
[{q:"'Vous êtes libre mardi ?' means:",opts:["Are you free on Tuesday?","What time on Tuesday?","Is Tuesday a holiday?","When is Tuesday?"],a:0,ex:"'Libre' = free/available; the question checks your availability on Tuesday."},{q:"'Le rendez-vous est à midi et demi.' means:",opts:["at 12:00","at 12:30","at 1:30","at 11:30"],a:1,ex:"'Midi' = noon and 'et demi' adds 30 minutes: 12:30."},{q:"'Je dois malheureusement annuler' means:",opts:["I need to move it to later","I unfortunately have to cancel","I'm unfortunately running late","I'll be there a bit early"],a:1,ex:"'Annuler' = to cancel; 'reporter' would mean to postpone."},{q:"'Ça vous convient à 10 heures ?' asks if:",opts:["10 o'clock suits you","it is 10 o'clock now","you are late","the meeting has ended"],a:0,ex:"'Convenir à quelqu'un' = to suit someone; it checks whether the time works."},{q:"'Prendre rendez-vous' means:",opts:["to cancel an appointment","to make an appointment","to be late for a meeting","to arrive early"],a:1,ex:"'Prendre rendez-vous' = to book an appointment; 'annuler' = to cancel."},{q:"To book an appointment with a doctor you say:",opts:["Je voudrais prendre rendez-vous avec le médecin.","Je voudrais faire un médecin pour le rendez-vous.","J'ai voulu prendre le médecin pour un rendez-vous.","Je veux un rendez-vous au médecin tout de suite."],a:0,ex:"'Prendre rendez-vous avec quelqu'un' is the set phrase, and 'je voudrais' keeps it polite."}],
[{q:"'Il pleut' means:",opts:["It's snowing","It's sunny","It's raining","It's cloudy"],a:2,ex:"'Il pleut' comes from pleuvoir (to rain); 'il neige' = it's snowing."},{q:"'Nuageux' means:",opts:["windy","sunny","foggy","cloudy"],a:3,ex:"'Nuageux' comes from 'le nuage' (cloud)."},{q:"'Quel temps fera-t-il demain ?' means:",opts:["What is the weather like now?","What will the weather be tomorrow?","Was it cold yesterday?","What was the forecast today?"],a:1,ex:"'Fera' is the future of faire, and 'demain' = tomorrow."},{q:"'Il fait chaud' means:",opts:["It's cold","It's hot","It's wet","It's windy"],a:1,ex:"Weather often uses 'il fait' + adjective: il fait chaud (hot), il fait froid (cold)."},{q:"'La neige' means:",opts:["rain","snow","sun","wind"],a:1,ex:"'La neige' = snow; 'la pluie' = rain, 'le soleil' = sun, 'le vent' = wind."},{q:"'Il fait plus froid aujourd'hui qu'hier' means today is:",opts:["warmer than yesterday","colder than yesterday","as cold as yesterday","the coldest day of the year"],a:1,ex:"'Plus froid que' = colder than; 'hier' = yesterday."}],
[{q:"'Veuillez agréer...' is used:",opts:["at the start of a formal email","at the end of a formal email","in informal messages","in spoken farewells"],a:1,ex:"'Veuillez agréer... mes salutations distinguées' is a formal closing formula."},{q:"'Madame, Monsieur' translates as:",opts:["Hi everyone","Dear Sir or Madam","Hello friends","Dear colleagues"],a:1,ex:"'Madame, Monsieur,' is the formal opening when you don't know the recipient's name."},{q:"'Je me réfère à votre e-mail du...' means:",opts:["I am replying immediately","I refer to your email of...","I am forwarding your message","I have not received your email"],a:1,ex:"'Se référer à' = to refer to; it links your message to an earlier one."},{q:"An informal email might open with:",opts:["Madame, Monsieur,","Salut Tom,","Veuillez agréer,","Cordialement,"],a:1,ex:"'Salut' + first name is a casual opening; 'Cordialement' is a closing."},{q:"'Veuillez trouver ci-joint...' means:",opts:["Please find attached...","I am writing because...","Best regards...","See you soon..."],a:0,ex:"'Ci-joint' = attached (herewith), used to point to an attachment."},{q:"Email to your boss: 'Je ne pourrai pas venir aujourd'hui car ___.'",opts:["j'ai mal la gorge","je suis mal à la gorge","j'ai mal à la gorge","j'ai mal au gorge"],a:2,ex:"Pain is 'avoir mal à' + body part; 'gorge' is feminine, so 'à la gorge'."}],
[{q:"'Où est le distributeur automatique le plus proche ?' means:",opts:["Where is the nearest bus stop?","Where is the nearest ATM?","Where is the hotel?","Where is the nearest pharmacy?"],a:1,ex:"'Un distributeur (automatique de billets)' is a cash machine / ATM."},{q:"'Un aller simple pour Paris, s'il vous plaît.' means:",opts:["One return ticket to Paris, please","One one-way ticket to Paris, please","One first-class seat to Paris, please","One night in a Paris hotel, please"],a:1,ex:"'Un aller simple' is one-way; a return ticket is 'un aller-retour'."},{q:"'Le train a du retard ?' means:",opts:["Is the train fast?","Does the train have a dining car?","Is the train delayed?","Has the train departed?"],a:2,ex:"'Avoir du retard' = to be late / delayed."},{q:"'Changer de train' means:",opts:["to board","to change trains","to arrive","to buy a ticket"],a:1,ex:"'Changer de' + noun without article means to switch: changer de train."},{q:"'Les bagages' means:",opts:["the ticket","the luggage","the platform","the seat"],a:1,ex:"'Les bagages' = luggage; 'le billet' = ticket, 'le quai' = platform, 'la place' = seat."},{q:"At a pharmacy: 'Vous avez quelque chose contre ___ ?' (a cough)",opts:["le genou","la tête","le ventre","la toux"],a:3,ex:"'La toux' = cough (from tousser); 'le genou' = knee, 'la tête' = head, 'le ventre' = stomach."}],
[{q:"In a story, which tense describes the background (e.g. 'Il faisait beau, les enfants jouaient')?",opts:["Passé composé","Présent","Imparfait","Futur simple"],a:2,ex:"The imparfait sets the scene and ongoing actions; the passé composé gives the main events."},{q:"'Il raconta que...' introduces:",opts:["a question","indirect speech","a command","a comparison"],a:1,ex:"'Raconter que' (to tell that) introduces what someone said: indirect speech."},{q:"'Pour conclure' means:",opts:["At first","On the other hand","In the middle","In conclusion"],a:3,ex:"'Conclure' = to conclude; 'pour conclure' signals the ending of a story or text."},{q:"'D'abord... ensuite... puis...' are used to:",opts:["compare","sequence events","ask questions","negate"],a:1,ex:"'D'abord' (first), 'ensuite' (next) and 'puis' (then) put events in order."},{q:"'Soudain' means:",opts:["slowly","suddenly","finally","never"],a:1,ex:"'Soudain' = suddenly; it often introduces a passé composé event after an imparfait scene."},{q:"'C'était le ___ jour de mes vacances !' (best)",opts:["meilleur","mieux","plus bon","bien"],a:0,ex:"'Meilleur' is the adjective (le meilleur jour); 'mieux' is the adverb and 'plus bon' is wrong."}]
],
B1:[
[{q:"Which phrase introduces a personal opinion?",opts:["Il est connu que","À mon avis","Selon les statistiques","On dit que"],a:1,ex:"'À mon avis' = in my opinion; the others present facts or other people's views."},{q:"'Je suis d'avis que...' means:",opts:["It is said that...","It is a fact that...","I am of the opinion that...","Studies show that..."],a:2,ex:"'Être d'avis que' = to be of the opinion that: a personal view."},{q:"Which phrase gives an opinion in the most tentative, hedged way?",opts:["Je suis sûr que","Il me semble que","Je suis convaincu que","Il est évident que"],a:1,ex:"'Il me semble que' (it seems to me) softens the claim; the others express certainty."},{q:"'Je (ne) suis (pas) d'accord' expresses:",opts:["a polite request","agreement or disagreement","a future plan or intention","a strong command"],a:1,ex:"'Être d'accord' = to agree; with 'ne... pas' it expresses disagreement."},{q:"Affirmative 'Je trouve que...' is followed by which mood?",opts:["subjunctive","indicative","imperative","infinitive"],a:1,ex:"Affirmative opinion verbs (trouver, penser, croire que) take the indicative."},{q:"'Qu'est-ce que tu penses de ce film ?' – 'J'___ pense beaucoup de bien.'",opts:["y","en","le","lui"],a:1,ex:"In 'penser du bien de quelque chose', de + noun is replaced by 'en'."}],
[{q:"Which word for 'because' cannot begin a sentence?",opts:["car","parce que","puisque","comme"],a:0,ex:"'Car' is a coordinating conjunction and must follow the main clause; 'comme' usually comes first."},{q:"Which conjunction introduces a subordinate clause?",opts:["et puis","mais","car","bien que"],a:3,ex:"'Bien que' (although) is subordinating; et, mais and car are coordinating conjunctions."},{q:"'Bien que' requires which mood?",opts:["indicatif","conditionnel","subjonctif","infinitif"],a:2,ex:"'Bien que' always takes the subjunctive: bien qu'il soit tard."},{q:"'Si' + present is followed by which tense in the result clause?",opts:["present or future","conditional","subjunctive","past conditional"],a:0,ex:"Real conditions: si + présent → présent or futur (Si tu viens, on ira au cinéma)."},{q:"The relative pronoun 'dont' replaces a complement introduced by:",opts:["à","de","pour","sur"],a:1,ex:"'Dont' replaces de + noun: le livre dont je parle (parler de)."},{q:"'C'est un collègue ___ j'apprécie la rigueur.'",opts:["que","qui","dont","où"],a:2,ex:"'La rigueur de ce collègue' contains 'de', so the relative pronoun is 'dont'."}],
[{q:"'La candidature' means:",opts:["the starting salary","the job application","the promotion","the final deadline"],a:1,ex:"'Poser sa candidature' = to apply; 'la candidature' is the application."},{q:"'Je suis responsable du projet' means:",opts:["I am interested in the project","I am responsible for the project","I created the project","I finished the project"],a:1,ex:"'Être responsable de' = to be in charge of / responsible for."},{q:"'L'entretien d'embauche' is:",opts:["a pay raise","a resignation letter","a job interview","a work contract"],a:2,ex:"'Embaucher' = to hire, so 'l'entretien d'embauche' is the job interview."},{q:"'Le CV' is the:",opts:["cover letter","resume","contract","reference"],a:1,ex:"The CV is your resume; a cover letter is 'une lettre de motivation'."},{q:"'Faire des heures supplémentaires' means:",opts:["to take a break","to work overtime","to quit","to be promoted"],a:1,ex:"'Heures supplémentaires' = extra hours beyond the contract, i.e. overtime."},{q:"'Tu travailles au bureau ce matin ?' – 'Oui, j'___ travaille.'",opts:["en","y","le","la"],a:1,ex:"'Y' replaces a place introduced by à/au/en: travailler au bureau → y travailler."}],
[{q:"'Le titre' (in a news context) means:",opts:["a documentary","a headline","an advertisement","an editorial"],a:1,ex:"In the press, 'le titre' is the headline; 'la une' is the front page."},{q:"'Selon un rapport' means:",opts:["according to a report","before the report","despite the report","without a report"],a:0,ex:"'Selon' = according to; it attributes information to a source."},{q:"In a news report, 'd'après le porte-parole' means:",opts:["according to the spokesperson","despite the spokesperson","after the spokesperson left","against the spokesperson"],a:0,ex:"'D'après' + source = according to; it signals reported, attributed information."},{q:"'L'émission' means:",opts:["the daily newspaper","the TV/radio programme","the front-page headline","the journalist"],a:1,ex:"'Une émission' is a TV or radio programme; 'le journal' is the newspaper or news bulletin."},{q:"When listening to the news, the best strategy is to focus on:",opts:["every single word","key words and context","only the last sentence","the speaker's accent"],a:1,ex:"Gist listening relies on key words and context; chasing every word overloads you."},{q:"'Elle a une quarantaine d'années, les cheveux gris et l'air sérieux' describes:",opts:["a place in a city","a recent event","a person's appearance","a small company"],a:2,ex:"Age ('une quarantaine d'années'), hair and 'l'air sérieux' all describe what someone looks like."}],
[{q:"'Tu devrais dormir plus.' expresses:",opts:["a command","advice","a fact","a question"],a:1,ex:"The conditional 'tu devrais' (you should) gives advice rather than an order."},{q:"'Je vous conseille de...' means:",opts:["I refuse to...","I demand that...","I would recommend...","I regret that..."],a:2,ex:"'Conseiller de' + infinitive = to advise / recommend doing something."},{q:"'À ta place, je...' means:",opts:["If I were you, I would...","You should never...","Instead of that, I...","On your behalf, I..."],a:0,ex:"'À ta place' = in your place, i.e. if I were you; it is followed by the conditional."},{q:"'Devrais' is the ___ of devoir.",opts:["present","conditional","imperfect","future"],a:1,ex:"'Je/tu devrais' is the conditional of devoir, used to soften obligation into advice."},{q:"'Il vaudrait mieux que...' means:",opts:["It is better that...","It would be better if...","It was better when...","It will never be better..."],a:1,ex:"'Vaudrait' is the conditional of valoir: 'il vaudrait mieux' = it would be better."},{q:"'Des légumes ? Tu devrais ___ manger plus.'",opts:["en","y","les","leur"],a:0,ex:"'En' replaces a partitive or quantity noun (des légumes): tu devrais en manger."}],
[{q:"'Je voyagerai l'année prochaine.' uses which tense?",opts:["Passé composé","Imparfait","Futur simple","Conditionnel"],a:2,ex:"The ending -ai added to the infinitive (voyager-ai) forms the futur simple."},{q:"'J'ai l'intention d'étudier.' means:",opts:["I used to study","I intend to study","I finished studying","I should study"],a:1,ex:"'Avoir l'intention de' + infinitive = to intend to."},{q:"'Prochainement' means:",opts:["recently","forever","soon","rarely"],a:2,ex:"'Prochainement' = soon / shortly, from 'prochain' (next)."},{q:"The futur proche is formed with:",opts:["avoir + past participle","aller + infinitive","être + past participle","devoir + past participle"],a:1,ex:"Futur proche = aller in the present + infinitive: je vais partir."},{q:"'Je projette de partir' expresses:",opts:["a past event","a plan","a regret","a command"],a:1,ex:"'Projeter de' + infinitive = to plan to."},{q:"'Tu vas retourner en Italie ?' – 'Oui, je vais ___ retourner l'an prochain.'",opts:["en","y","le","la"],a:1,ex:"'Y' replaces a destination with en/à (en Italie): je vais y retourner."}],
[{q:"Which word introduces a reported statement: 'Il dit ___ il est content.'?",opts:["si","parce que","que","bien que"],a:2,ex:"Reported statements use 'que'; 'si' introduces reported yes/no questions."},{q:"'Il a dit qu'il ___ fatigué.'",opts:["était","soit","sera","être"],a:0,ex:"After a past reporting verb, a present-tense statement shifts to the imparfait."},{q:"'Elle a demandé si je viendrais' uses which tense in the subordinate clause?",opts:["futur","conditionnel","subjonctif","imparfait"],a:1,ex:"'Viendrais' is the conditional, used as a future-in-the-past after a past reporting verb."},{q:"After a past reporting verb ('Il a dit que...'), the present tense shifts to:",opts:["the future","the imparfait","the subjunctive","the conditional"],a:1,ex:"'Je suis malade' → 'Il a dit qu'il était malade': présent becomes imparfait."},{q:"'On dit que...' is a way to:",opts:["give a polite order","report general claims","express a strong wish","ask a direct question"],a:1,ex:"'On dit que' (people say that) reports hearsay without naming a source."},{q:"'Il m'a dit qu'il avait trois enfants.' → 'Il m'a dit qu'il ___ avait trois.'",opts:["y","les","en","leur"],a:2,ex:"'En' replaces a noun after a number (trois enfants); the number stays: il en avait trois."}],
[{q:"'C'est dû au fait que...' means:",opts:["It is unrelated to...","It follows that...","It is due to the fact that...","It is possible that..."],a:2,ex:"'Dû à' = due to; the phrase explains a cause."},{q:"'Trouver une solution' means:",opts:["to cause a problem","to find a solution","to avoid an issue","to discuss options"],a:1,ex:"'Trouver' = to find; 'une solution' is a direct cognate."},{q:"'Tout d'abord' means:",opts:["finally","in addition","first of all","however"],a:2,ex:"'Tout d'abord' = first of all; it opens a list of steps or arguments."},{q:"'Le problème, c'est que...' introduces:",opts:["a proposed solution","the problem itself","a polite greeting","the final conclusion"],a:1,ex:"This structure names the topic first, then states what the problem actually is."},{q:"'Parvenir à un compromis' means:",opts:["to start a fight","to reach a compromise","to give up","to win"],a:1,ex:"'Parvenir à' = to reach / manage to achieve."},{q:"'Ne t'inquiète pas pour ce problème, je m'___ occupe.'",opts:["en","y","le","lui"],a:0,ex:"'S'occuper de quelque chose': de + noun is replaced by 'en', so je m'en occupe."}],
[{q:"A French essay introduction typically ends with:",opts:["an announcement of the plan","a list of examples","the final conclusion","a personal anecdote"],a:0,ex:"A French introduction moves from a hook to the 'problématique' and ends by announcing the plan."},{q:"'D'une part... d'autre part...' is used to:",opts:["list several examples","show contrast and balance","sum up the argument","introduce a quotation"],a:1,ex:"'D'une part... d'autre part' (on the one hand... on the other) balances two aspects."},{q:"'En somme' means:",opts:["To begin with...","By contrast...","In summary...","For example..."],a:2,ex:"'En somme' = in short / all in all; it sums up what has been said."},{q:"The three parts of a French dissertation are:",opts:["introduction, développement, conclusion","accroche, citation, résumé","titre, exemples, bibliographie","question, réponse, résumé"],a:0,ex:"Every dissertation has an introduction, a 'développement' (the body) and a conclusion."},{q:"'Par exemple' means:",opts:["in conclusion","for example","however","therefore"],a:1,ex:"'Par exemple' introduces an illustration of a point."},{q:"Correct adjective position and agreement:",opts:["une maison grande blanche","une blanche grande maison","un grand maison blanc","une grande maison blanche"],a:3,ex:"Short common adjectives like 'grand' go before the noun, colours after; both agree with 'maison' (f.)."}],
[{q:"'Parlez-moi de vous.' means:",opts:["Where do you work?","Tell me about yourself.","What are your weaknesses?","Why do you want this job?"],a:1,ex:"'Parler de' = to talk about, so 'parlez-moi de vous' = tell me about yourself."},{q:"'Mes points forts sont...' means:",opts:["My goals are...","My weaknesses are...","My strengths are...","My experience is..."],a:2,ex:"'Points forts' = strengths; weaknesses are 'points faibles'."},{q:"'Avez-vous des questions ?' means:",opts:["Do you have references?","Are you available now?","Do you have any questions?","Can you start immediately?"],a:2,ex:"Inversion (avez-vous) forms a formal question: do you have any questions?"},{q:"'Pourquoi postulez-vous ?' asks:",opts:["When can you start?","Why are you applying?","What is your salary?","Where do you live?"],a:1,ex:"'Postuler' = to apply (for a job), and 'pourquoi' = why."},{q:"A good interview answer should be:",opts:["long and general","concrete, with examples","short, with no details","focused on salary"],a:1,ex:"Concrete examples make your skills credible to the interviewer."},{q:"'Décrivez-vous en trois mots' (a woman answers):",opts:["Je suis curieuse, organisée et dynamique.","Je suis curieux, organisée et dynamiques.","Je suis curieuse, organisé et dynamique.","Je suis curieuses, organisées et dynamique."],a:0,ex:"All three adjectives agree with a female singular speaker; 'dynamique' already ends in -e."}]
],
B2:[
[{q:"'Il ne faut pas perdre de vue que...' means:",opts:["We must not lose sight of the fact that...","We must not mention the fact that...","We cannot see why it is true that...","We should stop pretending that..."],a:0,ex:"'Perdre de vue' = to lose sight of; the phrase reminds listeners of a key point."},{q:"To concede a point in a debate, use:",opts:["Certes, mais...","Non, jamais...","C'est absolument faux...","Comme je l'ai dit..."],a:0,ex:"'Certes' grants the opponent a point before 'mais' introduces your counter-argument."},{q:"'En définitive' means:",opts:["on the other hand","ultimately","by contrast","in addition"],a:1,ex:"'En définitive' = ultimately / when all is said and done; it introduces a final judgement."},{q:"'Il est indéniable que...' means:",opts:["It is doubtful that...","It is undeniable that...","It is irrelevant that...","It is unclear that..."],a:1,ex:"'Indéniable' = undeniable, from 'nier' (to deny)."},{q:"'Je partage (ne partage pas) cet avis' expresses:",opts:["a greeting","(dis)agreement","a request","a summary"],a:1,ex:"'Partager un avis' = to share an opinion, i.e. to agree."},{q:"'Si l'on suivait votre logique, on ___ toutes les écoles.'",opts:["fermera","fermerait","ferme","fermait"],a:1,ex:"Si + imparfait (suivait) calls for the conditional présent in the main clause."}],
[{q:"Which sentence is in the passive voice?",opts:["Le texte est lu par les élèves.","Les élèves lisent le texte.","Les élèves ont lu le texte.","Le texte, les élèves le lisent."],a:0,ex:"The passive is être + past participle, with the agent introduced by 'par'."},{q:"'Le projet a été financé par l'État.' uses:",opts:["the active voice","the passive voice","a pronominal verb","an impersonal verb"],a:1,ex:"'A été' + participle (financé) is the passé composé of the passive."},{q:"'La décision sera annoncée demain.' is:",opts:["a past action","a future passive","a present state","a habitual action"],a:1,ex:"'Sera' (future of être) + participle forms the future passive."},{q:"The agent of a passive verb is introduced by:",opts:["par (or de)","pour (or à)","sur","avec"],a:0,ex:"The agent follows 'par', or 'de' with verbs of feeling or state: aimé de tous."},{q:"'On' as a subject is often used to avoid the:",opts:["future","passive","subjunctive","imperative"],a:1,ex:"French often prefers 'on' + active verb to a passive: on a vendu la maison."},{q:"'Si le projet avait été accepté, il ___ l'an dernier.'",opts:["serait lancé","sera lancé","aurait été lancé","était lancé"],a:2,ex:"Si + plus-que-parfait requires the past conditional; in the passive: aurait été lancé."}],
[{q:"'Non seulement... mais aussi...' means:",opts:["neither... nor...","not only... but also...","either... or...","if... then..."],a:1,ex:"'Non seulement... mais aussi' adds a second, often stronger, element."},{q:"'Plus tu pratiques, mieux tu parles.' shows:",opts:["contrast","proportion","concession","reason"],a:1,ex:"'Plus..., plus/mieux...' links two things that increase together: proportion."},{q:"'Alors que' is used to:",opts:["add information","show a condition","express contrast","give an example"],a:2,ex:"'Alors que' contrasts two facts (whereas) or marks simultaneity (while)."},{q:"'Soit... soit...' means:",opts:["both... and...","either... or...","neither... nor...","not only..."],a:1,ex:"'Soit... soit...' presents two alternatives: either... or."},{q:"'Tandis que' expresses:",opts:["cause","contrast","purpose","condition"],a:1,ex:"'Tandis que' (whereas / while) sets two facts against each other."},{q:"'À condition que' and 'pourvu que' are followed by:",opts:["the indicative","the subjunctive","the conditional","the future"],a:1,ex:"Both are conjunctions of condition that always take the subjunctive: pourvu qu'il vienne."}],
[{q:"'Selon les sources gouvernementales' means:",opts:["against government sources","according to government sources","beyond government statements","despite government sources"],a:1,ex:"'Selon' = according to; the information is attributed to the government."},{q:"'Le recul' (in economic news) means:",opts:["an increase","a recovery","a decline","an announcement"],a:2,ex:"'Le recul' = a fall/decline, from 'reculer' (to move back): le recul du chômage."},{q:"'Les réactions ont été mitigées.' means:",opts:["Reactions were positive","Reactions were negative","Reactions were mixed","There were no reactions"],a:2,ex:"'Mitigé' = mixed / lukewarm, not 'mitigated': a classic false friend."},{q:"'La hausse' means:",opts:["the rise","the fall","the report","the cause"],a:0,ex:"'La hausse' = rise / increase; its opposite is 'la baisse'."},{q:"To distinguish fact from opinion in an article, look for:",opts:["emotive wording versus data","the length of the article","the size of the headline","the date of publication"],a:0,ex:"Opinion shows in evaluative, emotive words; facts come with figures and sources."},{q:"In the news, 'Le ministre aurait démissionné' signals:",opts:["a confirmed fact","a future hypothesis","an unconfirmed report","an official order"],a:2,ex:"The journalistic conditional (aurait démissionné) reports information not yet verified."}],
[{q:"Which is the most formal way to say 'get help'?",opts:["bénéficier d'une aide","avoir de l'aide","choper de l'aide","se faire aider"],a:0,ex:"'Bénéficier de' belongs to formal/administrative French; 'choper' is slang."},{q:"'Par la présente' is used in:",opts:["casual conversation","formal documents","text messages","media headlines"],a:1,ex:"'Par la présente' (hereby) is a fixed formula in official letters and documents."},{q:"'Je t'envoie un msg' is:",opts:["formal","technical","colloquial","literary"],a:2,ex:"'Tu' and the abbreviation 'msg' mark an informal, colloquial register."},{q:"Register refers to the level of:",opts:["volume","formality","speed","regional accent"],a:1,ex:"Register is the degree of formality chosen for a situation: familier, courant, soutenu."},{q:"'Bouquin' (for book) belongs to ___ register.",opts:["very formal","colloquial","academic","legal"],a:1,ex:"'Bouquin' is everyday familiar French for 'livre'."},{q:"Most formal way to ask for help:",opts:["Auriez-vous l'amabilité de m'aider ?","Tu aurais la gentillesse de m'aider ?","Vous pourriez pas m'aider un peu, là ?","Tu peux me filer un coup de main ?"],a:0,ex:"'Auriez-vous l'amabilité de...' combines vous, inversion and the conditional: the most formal."}],
[{q:"'Nous pourrions envisager un compromis.' means:",opts:["We reject the proposal","We could consider a compromise","We demand a different solution","We have no flexibility"],a:1,ex:"The conditional 'pourrions' + 'envisager' (to consider) makes a cautious opening."},{q:"'C'est non négociable' means:",opts:["that is negotiable","that is not up for discussion","that depends on the price","we can discuss this later"],a:1,ex:"'Non négociable' = cannot be negotiated; the point is closed."},{q:"'Sous réserve' means:",opts:["unconditionally","without notice","conditionally","formally agreed"],a:2,ex:"'Sous réserve de' = subject to / on condition of: sous réserve d'acceptation."},{q:"'Faire une proposition' means:",opts:["to reject an offer","to make a proposal","to sign a contract","to end talks"],a:1,ex:"'Faire une proposition' = to put forward an offer or proposal."},{q:"'Couper la poire en deux' in a negotiation means:",opts:["to break off talks","to split the difference","to share the profits","to raise the stakes"],a:1,ex:"Literally 'cut the pear in half': each side gives up part of its demand to meet halfway."},{q:"'Si vous baissiez le prix de 10 %, nous ___ la commande.'",opts:["doublerions","doublerons","doublions","avons doublé"],a:0,ex:"Si + imparfait (baissiez) → conditionnel présent in the main clause: nous doublerions."}],
[{q:"Which is a nominalized infinitive?",opts:["le savoir","savoir","le savant","savait"],a:0,ex:"An infinitive with an article becomes a noun: le savoir (knowledge), le devoir (duty)."},{q:"'Le développement durable' means:",opts:["technological innovation","sustainable development","rapid economic growth","long-term productivity"],a:1,ex:"'Durable' = lasting / sustainable, so 'le développement durable' is sustainable development."},{q:"Abstract noun from the adjective 'libre':",opts:["la liberté","la libre","le libre","la libération"],a:0,ex:"'Libre' → 'la liberté' (freedom); 'la libération' derives from the verb 'libérer'."},{q:"A nominalized infinitive takes the article:",opts:["la","le","les","une"],a:1,ex:"Nominalized infinitives are masculine: le rire, le pouvoir, le savoir-faire."},{q:"'La justice' is the abstract noun from:",opts:["juste","jour","jeu","joie"],a:0,ex:"The adjective 'juste' + suffix -ice gives 'la justice'."},{q:"'L'hypothèse' means:",opts:["the hypocrisy","the hypothesis","the mortgage","the habit"],a:1,ex:"'L'hypothèse' = hypothesis; don't confuse it with 'l'hypothèque' (mortgage)."}],
[{q:"In an argument, 'la thèse' is:",opts:["a set of examples","a counter-argument","the main claim","a short summary"],a:2,ex:"'La thèse' is the main position the text defends."},{q:"'L'argument central est que...' introduces:",opts:["a conclusion","the main claim","a supporting detail","a question"],a:1,ex:"'Central' marks the core claim around which the other arguments are organised."},{q:"'Pour étayer cette thèse...' means:",opts:["Against this idea...","The problem is...","To support this thesis...","Despite this..."],a:2,ex:"'Étayer' (literally to prop up) means to support with evidence."},{q:"'En revanche, on peut objecter que...' introduces:",opts:["further support","a counter-argument","a concrete example","the conclusion"],a:1,ex:"'En revanche' (on the other hand) + 'objecter' (to object) introduces a counter-argument."},{q:"A solid argument structure is:",opts:["claim, reason, example","example, example, example","claim, claim, claim","question, question, answer"],a:0,ex:"Each claim is justified by a reason and illustrated by a concrete example."},{q:"'Si les impôts augmentent, la consommation baissera' expresses:",opts:["a past regret","an impossible wish","a real, likely condition","a polite request"],a:2,ex:"Si + présent → futur expresses a real, likely condition."}],
[{q:"To signal the end of a section in a presentation:",opts:["Pour résumer ce point...","Premièrement...","Pour être honnête...","Permettez-moi de commencer..."],a:0,ex:"'Résumer' = to sum up; it closes one section before moving on."},{q:"'Comme vous pouvez le voir sur ce graphique...' means:",opts:["As the graph clearly proves...","As you can see from this graph...","The graph is missing some data...","The graph contradicts this point..."],a:1,ex:"'Comme vous pouvez le voir' = as you can see; 'le graphique' is the chart."},{q:"A rhetorical question in a presentation is used to:",opts:["get an answer from the audience","engage the audience in the next point","avoid a difficult topic","fill silence at the end"],a:1,ex:"A rhetorical question expects no answer; it draws listeners in and introduces a point."},{q:"'Permettez-moi d'expliquer brièvement...' means:",opts:["Let me conclude...","Let me briefly explain...","Let me disagree...","Let me leave..."],a:1,ex:"'Permettez-moi de' = allow me to; 'brièvement' = briefly."},{q:"Good signposting in a presentation helps the audience:",opts:["follow the structure","memorise the slides","read the handout","skip the details"],a:0,ex:"Signposts (d'abord, passons à, pour conclure) show where you are in the talk."},{q:"Ending a presentation: 'Si vous avez des questions, n'___ pas.'",opts:["hésitez","hésiteriez","hésitiez","hésiterez"],a:0,ex:"'N'hésitez pas' is the negative vous imperative: ne + hésitez + pas."}],
[{q:"'Je suggère de raccourcir ce paragraphe.' means:",opts:["I demand this paragraph be removed","I suggest shortening this paragraph","I think this paragraph is perfect","I disagree with this paragraph"],a:1,ex:"'Suggérer de' + infinitive = to suggest doing; 'raccourcir' = to shorten."},{q:"'L'argument gagnerait à être mieux étayé.' means:",opts:["It would benefit from better support","It has already won the debate","It needs no further evidence","It would be better removed entirely"],a:0,ex:"'Gagner à' + infinitive = to benefit from; the conditional makes the criticism tactful."},{q:"Constructive feedback includes:",opts:["only criticism","only praise","specific suggestions for improvement","personal opinions about the author"],a:2,ex:"Constructive feedback points to concrete ways of improving the work, not the person."},{q:"'J'apprécie particulièrement que...' is a way to:",opts:["criticise harshly","give positive feedback","end the talk","ask a question"],a:1,ex:"'Apprécier' = to appreciate; the phrase opens with praise."},{q:"Good peer feedback is:",opts:["harsh but brief","specific and respectful","polite but vague","focused on the author"],a:1,ex:"Useful feedback names precise points and stays courteous."},{q:"Softest peer feedback: '___ ajouter un exemple ici.'",opts:["Tu pourrais peut-être","Tu dois absolument","Il faut forcément","Tu vas devoir"],a:0,ex:"Conditional 'pourrais' + 'peut-être' turns an instruction into a gentle suggestion."}]
],
C1:[
[{q:"'À peine' is best translated as:",opts:["almost","barely","mostly","slightly"],a:1,ex:"'À peine' = hardly/barely: il a à peine mangé (he barely ate)."},{q:"'Certes... mais...' expresses:",opts:["a simple addition","concession then contrast","cause and effect","a choice of alternatives"],a:1,ex:"'Certes' concedes a point, then 'mais' contrasts it with the writer's real position."},{q:"'Dans une certaine mesure' means:",opts:["without doubt","to some extent","in contrast","precisely"],a:1,ex:"'Dans une certaine mesure' limits a claim: to a certain extent."},{q:"'Plutôt' often signals:",opts:["a strong claim","a nuanced preference","a firm command","a full negation"],a:1,ex:"'Plutôt' (rather / fairly) softens or nuances: c'est plutôt réussi."},{q:"'Quasiment' means:",opts:["never","almost","hardly","loudly"],a:1,ex:"'Quasiment' = almost / virtually, a slightly informal synonym of 'presque'."},{q:"'Nous avons pris bonne note de votre remarque' is, in business:",opts:["a polite, non-committal reply","an enthusiastic agreement","a firm, final refusal","a promise to act quickly"],a:0,ex:"'Prendre bonne note' only acknowledges the remark, without promising any action."}],
[{q:"'La problématique centrale est...' signals:",opts:["a methodological detail","the core issue of the text","a secondary argument","the final conclusion"],a:1,ex:"'La problématique' is the central question a text or essay sets out to address."},{q:"A 'note de bas de page' is:",opts:["a heading","a footnote","a bibliography","an abstract"],a:1,ex:"'Bas de page' = bottom of the page, hence a footnote."},{q:"'La présente étude montre' means:",opts:["The future study will show","The present study shows","The past study showed","The theoretical study predicts"],a:1,ex:"'Présent(e)' before the noun means 'this / current': la présente étude = this study."},{q:"'Exposer' in academic French means:",opts:["to set out","to hide away","to leave out","to cut short"],a:0,ex:"In academic French 'exposer' means to present ideas (un exposé = a presentation)."},{q:"Academic citations serve to:",opts:["support and attribute claims","make the text look longer","replace the writer's analysis","show off wide reading"],a:0,ex:"Citations back up claims with evidence and credit the original author."},{q:"In 'La mise en œuvre de la réforme a été retardée', 'la mise en œuvre' means:",opts:["the implementation","the cancellation","the evaluation","the funding"],a:0,ex:"'Mettre en œuvre' = to implement, so 'la mise en œuvre' is the implementation."}],
[{q:"'Ça ne casse pas trois pattes à un canard.' means:",opts:["It is dangerous","It's nothing special","It is very fast","It is a lie"],a:1,ex:"Literally 'it doesn't break a duck's three legs': it's nothing extraordinary."},{q:"'Prendre quelqu'un pour un pigeon' means:",opts:["to be kind to someone","to take someone for a fool","to flatter someone","to ignore someone"],a:1,ex:"A 'pigeon' is a gullible dupe; the idiom means to fool or swindle someone."},{q:"'Avoir le cafard' means:",opts:["to have a headache","to be afraid of insects","to feel down","to be very tired"],a:2,ex:"'Le cafard' (cockroach) idiomatically means low spirits: avoir le cafard = to feel blue."},{q:"'Tomber dans les pommes' means:",opts:["to faint","to fall asleep","to be late","to succeed"],a:0,ex:"'Tomber dans les pommes' is a colloquial idiom for fainting (s'évanouir)."},{q:"Whether an idiom is appropriate depends mainly on the:",opts:["length of the text","context and audience","speaker's accent","topic's difficulty"],a:1,ex:"Many idioms are familiar in register, so they suit some situations and listeners but not others."},{q:"In a meeting, 'faire le point' means:",opts:["to argue a point","to end the meeting","to take stock","to vote"],a:2,ex:"'Faire le point' = to review where things stand (originally to fix a ship's position)."}],
[{q:"Short, juxtaposed sentences in French prose create:",opts:["ambiguity","speed and tension","an academic tone","subordination"],a:1,ex:"Brief sentences without connectors quicken the pace and build tension."},{q:"Anaphore is the repetition of:",opts:["a word at the end of clauses","a word at the start of successive clauses","a punctuation mark for emphasis","an idea in reverse order"],a:1,ex:"Anaphora repeats a word or phrase at the start of successive clauses or lines."},{q:"'Il fait nuit. Les rues sont vides. Personne ne parle.' uses:",opts:["hypotaxe","parataxe","chiasme","litote"],a:1,ex:"Parataxis places clauses side by side without subordinating conjunctions."},{q:"Hypotaxe is characterised by:",opts:["short equal clauses","subordinate, nested clauses","an absence of verbs","a series of questions"],a:1,ex:"Hypotaxis links clauses through subordination (que, qui, parce que, bien que...)."},{q:"A long, subordinated sentence tends to feel more:",opts:["urgent","reflective","casual","fragmented"],a:1,ex:"Long periodic sentences slow the pace and suit argument or reflection."},{q:"Nominal style for 'Parce que les coûts ont augmenté, ...':",opts:["Parce que augmentation des coûts, ...","Du fait que augmenter les coûts, ...","Avec les coûts qui augmentation, ...","En raison de l'augmentation des coûts, ..."],a:3,ex:"Nominal style turns the verb into a noun (augmenter → l'augmentation) after 'en raison de'."}],
[{q:"'Parmi' must be followed by:",opts:["a plural or collective noun","a singular count noun","an infinitive","a subjunctive clause"],a:0,ex:"'Parmi' (among) needs a plural or collective noun: parmi les invités, parmi la foule."},{q:"'En dépit de' takes:",opts:["an indicative clause","a noun or pronoun","a subjunctive clause","a bare infinitive"],a:1,ex:"'En dépit de' is a preposition, so it takes a noun: en dépit des difficultés."},{q:"'Quand il arriva, elle avait déjà mangé.' The earlier action uses the:",opts:["imparfait","passé composé","plus-que-parfait","futur antérieur"],a:2,ex:"'Avait mangé' is the plus-que-parfait: an action completed before another past action."},{q:"The subjunctive follows expressions of:",opts:["certainty","doubt or emotion","known facts","daily habits"],a:1,ex:"Doubt, will, necessity and emotion trigger the subjunctive: je doute qu'il vienne."},{q:"The plus-que-parfait is formed with:",opts:["imparfait auxiliary + participle","présent auxiliary + participle","futur auxiliary + participle","conditionnel auxiliary + participle"],a:0,ex:"Plus-que-parfait = avoir/être in the imparfait + past participle: j'avais fini, elle était partie."},{q:"'Nous vous saurions gré de bien vouloir nous ___ ce document.'",opts:["retourner","retournez","retournerez","retournant"],a:0,ex:"'Bien vouloir' is followed by an infinitive: bien vouloir nous retourner ce document."}],
[{q:"'Le fil conducteur' of a lecture means:",opts:["a quotation","an error","the main thread","a transition"],a:2,ex:"'Le fil conducteur' is the guiding thread that links the parts of a talk."},{q:"An effective note-taking strategy is:",opts:["writing every word","paraphrasing key ideas","recording only numbers","drawing pictures only"],a:1,ex:"Paraphrasing key ideas is fast and forces you to process the meaning."},{q:"To check you understood a complex passage, you should:",opts:["read it in translation","summarise it in your own words","avoid re-reading it at all","underline every single line"],a:1,ex:"If you can restate the main points in your own words, you have understood them."},{q:"'L'idée maîtresse' is:",opts:["a minor detail","the core idea","the introduction","a footnote"],a:1,ex:"As an adjective 'maître / maîtresse' means main: l'idée maîtresse = the key idea."},{q:"Connectors in a lecture (donc, ainsi) signal:",opts:["a change of speaker","logical structure","a pause for questions","an unrelated aside"],a:1,ex:"Connectors such as donc and ainsi mark consequences and show how ideas link."},{q:"'Passons au point suivant de l'ordre du jour' means:",opts:["Let's go back to the start","Let's move on to the next item","Let's take a short break","Let's vote on this now"],a:1,ex:"'Passer à' = to move on to; 'l'ordre du jour' is the agenda."}],
[{q:"A compte rendu should:",opts:["include the author's personal opinion","include your personal evaluation","present the main ideas neutrally","expand on the original argument"],a:2,ex:"A compte rendu restates the text's ideas objectively, without your own judgement."},{q:"'L'auteur soutient que...' signals:",opts:["a direct quotation","attributed reported speech","the reader's personal view","an implicit counter-argument"],a:1,ex:"'Soutenir que' = to argue / maintain that; it attributes a claim to the author."},{q:"The usual tense in a French summary of a text is the:",opts:["imparfait","présent","futur","plus-que-parfait"],a:1,ex:"Summaries describe a text's ideas in the present: l'auteur affirme, montre, conclut."},{q:"Beyond a neutral summary, a critical summary adds:",opts:["more plot detail","a reasoned evaluation","invented examples","longer quotations"],a:1,ex:"A critical summary assesses the text's arguments with justified judgements."},{q:"'Selon l'auteur' means:",opts:["against the author","according to the author","without the author","despite the author"],a:1,ex:"'Selon' = according to; it attributes the view to the author."},{q:"Which style suits a compte rendu?",opts:["subjective and emotional","a word-for-word transcript","objective and concise","familiar and chatty"],a:2,ex:"Use neutral wording, reformulate rather than copy, and keep it much shorter than the source."}],
[{q:"In a formal French letter, how is the opening 'Madame, Monsieur' punctuated?",opts:["comma, then the text starts with a capital","comma, then the text starts in lower case","no punctuation, then a capital letter","colon, then the text starts in lower case"],a:0,ex:"The salutation ends with a comma, and the first line of the body begins with a capital letter."},{q:"'Veuillez trouver ci-joint...' means:",opts:["I am requesting...","Please find attached...","I am responding to...","I am unable to send..."],a:1,ex:"'Ci-joint' = attached; 'veuillez trouver' = please find."},{q:"'Je t'envoie ça' vs 'je vous fais parvenir ce document' differs in:",opts:["tense","subject","formality","content"],a:2,ex:"Both mean 'I'm sending this'; tu/ça is familiar, vous/faire parvenir is formal."},{q:"'Veuillez agréer mes salutations distinguées' is:",opts:["an informal sign-off","a formal closing","a formal greeting","a polite request"],a:1,ex:"It is a standard formal closing formula placed at the end of a letter."},{q:"Formal writing prefers:",opts:["colloquial words","precise, neutral words","abbreviations","emotive language"],a:1,ex:"Formal French favours precise, neutral vocabulary over familiar or emotive words."},{q:"Correct formal closing:",opts:["Je vous prie d'agréer, Madame, à l'expression de mes salutations distinguées.","Veuillez agréer, Madame, de l'expression de mes salutations distinguées.","Je vous prie d'agréer, Madame, l'expression de mes bisous distingués.","Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées."],a:3,ex:"'Agréer' takes a direct object (no à/de), and 'bisous' breaks the formal register."}],
[{q:"A filler phrase to gain thinking time:",opts:["Eh bien, disons que...","Absolument pas, non.","C'est tout à fait faux.","Je vous l'ai déjà dit."],a:0,ex:"'Eh bien' and 'disons que' buy thinking time while signalling an answer is coming."},{q:"'Pour ainsi dire' means:",opts:["in great detail","so to speak","to put it bluntly","according to studies"],a:1,ex:"'Pour ainsi dire' (so to speak) flags that a word is used loosely."},{q:"Hedging language in spoken French signals:",opts:["absolute certainty","full commitment","caution or uncertainty","a change of topic"],a:2,ex:"Hedges (peut-être, il me semble, plus ou moins) soften claims and show caution."},{q:"'En quelque sorte' means:",opts:["in a way","never","exactly","by chance"],a:0,ex:"'En quelque sorte' = in a way / so to speak, softening a statement."},{q:"Spontaneous speech uses more ___ than writing.",opts:["footnotes","fillers and repairs","passive structures","formal citations"],a:1,ex:"Unplanned speech contains fillers (euh, bon) and self-corrections (enfin, je veux dire)."},{q:"To take the floor politely in a meeting:",opts:["Si vous me permettez, j'aimerais ajouter un point.","Laissez-moi parler, vous dites n'importe quoi.","Bon, moi je vais vous dire ce qui ne va pas.","Attendez, attendez, j'ai un truc à dire, là."],a:0,ex:"'Si vous me permettez' asks permission and the conditional 'j'aimerais' keeps it polite."}],
[{q:"Which word is a typical 'cheville' (empty filler) to cut from written prose?",opts:["parce que","franchement","afin que","bien que"],a:1,ex:"'Franchement' often adds nothing in writing; the conjunctions carry logical meaning."},{q:"Heavy passive constructions in French prose are often better replaced with:",opts:["more passive forms","the active voice","nominalised phrases","longer sentences"],a:1,ex:"French style generally prefers the active voice, which is more direct."},{q:"'Pléthorique' in editing describes:",opts:["a very short text","an overly long text","a well-balanced text","a technical text"],a:1,ex:"'Pléthorique' = excessive, overabundant: a bloated text that needs cutting."},{q:"Good editing improves:",opts:["the word count","clarity and concision","the page layout","the visual design"],a:1,ex:"Editing targets how clearly and economically the text says what it means."},{q:"Replacing a heavy noun phrase with a verb usually makes the text:",opts:["heavier","clearer","longer","vaguer"],a:1,ex:"'Nous avons procédé à l'analyse' → 'Nous avons analysé': the verb is more direct."},{q:"Which connector best replaces 'et aussi' in a formal report?",opts:["du coup","bref","en outre","genre"],a:2,ex:"'En outre' (moreover) is formal; 'du coup', 'bref' and 'genre' are colloquial."}]
],
C2:[
[{q:"Which sounds most natural for 'Right, I'm heading home' in everyday speech?",opts:["Bon, je rentre.","Bon, je vais à ma maison.","Bon, je retourne à ma maison.","Bon, je vais dans ma maison."],a:0,ex:"'Rentrer' alone means to go home; 'aller à ma maison' is a calque natives don't use."},{q:"'Ça se voit.' idiomatically means:",opts:["It is hidden","It's obvious","It's a matter of taste","It doesn't matter"],a:1,ex:"'Ça se voit' = it shows, i.e. it's obvious: Tu es fatigué ? – Ça se voit !"},{q:"In casual spoken French, the 'ne' of negation is often:",opts:["stressed","doubled","dropped","moved to the end"],a:2,ex:"In casual speech 'ne' is usually dropped: je sais pas, c'est pas grave."},{q:"'De toute façon' means:",opts:["never","anyway","exactly","by chance"],a:1,ex:"'De toute façon' = anyway / in any case, dismissing other considerations."},{q:"Native rhythm in French relies partly on:",opts:["ignoring all liaison","natural liaison and stress","stressing every syllable","very short words only"],a:1,ex:"French groups words with liaison and stresses the last syllable of each rhythmic group."},{q:"In a DALF C2-style oral exposé, which register fits?",opts:["familier throughout","controlled courant-soutenu","verlan, to sound natural","SMS-style abbreviations"],a:1,ex:"Examiners expect a controlled standard-to-formal register suited to an argued presentation."}],
[{q:"'Ch'est pas d'la tarte' is associated with which variety?",opts:["Quebec French","Belgian French","Ch'ti / Picard","Swiss French"],a:2,ex:"'Ch'' for 'c'' is typical of Picard / Ch'ti speech in northern France."},{q:"'Icitte' (= ici) is a marker of:",opts:["Southern French","Standard French","Quebec French","Belgian French"],a:2,ex:"'Icitte' is a well-known Quebec French form of 'ici'."},{q:"Neutral educated French is called:",opts:["argot parisien","verlan","français standard","argot"],a:2,ex:"'Le français standard' is the neutral norm; verlan and argot are slang."},{q:"'Septante' (70) is used in:",opts:["France and Quebec","Belgium and Switzerland","Quebec only","France and Belgium"],a:1,ex:"Belgium and French-speaking Switzerland say septante (70) and nonante (90)."},{q:"'Char' for car is typical of:",opts:["France","Belgium","Quebec","Switzerland"],a:2,ex:"In Quebec 'un char' is a car (in France: une voiture)."},{q:"Your synthèse uses a Belgian source with 'nonante'. You should:",opts:["reformulate as quatre-vingt-dix","present 'nonante' as the norm","delete the number entirely","translate it into English"],a:0,ex:"A synthèse is written in standard French and reformulates sources, so use quatre-vingt-dix."}],
[{q:"A gradation (climax) in French rhetoric moves:",opts:["from strong to weak","from weak to strong","randomly","from abstract to concrete"],a:1,ex:"Gradation builds intensity step by step: 'Va, cours, vole' (Corneille)."},{q:"Repetition as a rhetorical device mainly creates:",opts:["emphasis","irony","ambiguity","contrast"],a:0,ex:"Repeating a word insists on it and gives the sentence rhythm."},{q:"Parenthetical remarks are used to:",opts:["conclude the argument","add an aside","change the topic","introduce a quote"],a:1,ex:"A parenthesis inserts a comment or precision without breaking the main sentence."},{q:"A rhetorical question is meant to:",opts:["get a literal answer","guide the audience's thinking","check the audience is awake","end the speech politely"],a:1,ex:"It expects no answer; it steers listeners toward the speaker's conclusion."},{q:"A 'tricolon' groups elements in:",opts:["twos","threes","fours","fives"],a:1,ex:"A tricolon groups three parallel elements: 'Liberté, égalité, fraternité'."},{q:"'Non seulement..., mais encore...' in a final project serves to:",opts:["cancel the first idea","build up the argument","introduce a quotation","ask a question"],a:1,ex:"It adds a second, stronger point to the first, building the argument by gradation."}],
[{q:"Synesthésie mixes senses. Which example shows it?",opts:["une maison ancienne","une horloge rapide","un bleu silencieux","un grand mot"],a:2,ex:"'Un bleu silencieux' links a colour (sight) with silence (hearing)."},{q:"In 'ce marchand accoudé sur son comptoir avide', greed is given to the counter. This device is:",opts:["une hypallage","une litote","un oxymore","une anaphore"],a:0,ex:"Hypallage transfers an adjective from the word it logically fits (the merchant) to a nearby one."},{q:"In poetry, an 'enjambement' is:",opts:["a rhyme at the line end","a run-on into the next line","a break between stanzas","a repeated refrain"],a:1,ex:"Enjambment lets a sentence spill over the end of a line into the next."},{q:"A 'métaphore' works by:",opts:["imitating a sound","comparing without 'comme'","exaggerating a fact","softening a statement"],a:1,ex:"A metaphor equates two unlike things directly; a simile (comparaison) uses 'comme'."},{q:"'Personnification' gives human traits to:",opts:["historical figures","objects or ideas","the reader","the narrator"],a:1,ex:"Personification lends human qualities to things or abstractions: la ville s'endort."},{q:"Reformulate 'Il pleuvait des cordes' in a neutral register:",opts:["Il pleuvait un peu.","Il faisait très beau.","Il pleuvait très fort.","Il y avait du vent."],a:2,ex:"'Pleuvoir des cordes' (to rain ropes) is a familiar idiom for very heavy rain."}],
[{q:"'Le conseil juridique' is:",opts:["a judge's ruling","legal advice","a jury","a law court"],a:1,ex:"'Conseil juridique' = legal advice, or the adviser who gives it; a judge is 'un juge'."},{q:"'Le produit intérieur brut' is abbreviated as:",opts:["PIB","BRD","PNB","PCB"],a:0,ex:"PIB = produit intérieur brut (GDP); PNB is produit national brut (GNP)."},{q:"In economics, 'la déflation' describes:",opts:["a currency revaluation","a general drop in prices","a general rise in prices","a trade deficit"],a:1,ex:"Deflation is a sustained fall in the general price level; a rise is 'l'inflation'."},{q:"'L'hypothèse' in research is:",opts:["an established fact","a testable assumption","a final conclusion","a cited source"],a:1,ex:"A research hypothesis is a provisional claim to be tested, not a result."},{q:"Specialized vocabulary should be used:",opts:["everywhere","precisely and in context","to impress readers","as rarely as possible"],a:1,ex:"Technical terms help only when used accurately and suited to the audience."},{q:"In the DALF C2, 'le dossier' is:",opts:["a set of source documents","a folder of past grades","the candidate's CV","the examiner's notes"],a:0,ex:"The DALF C2 dossier is a set of texts and recordings that the candidate synthesises."}],
[{q:"Verbal irony typically consists in:",opts:["saying the opposite of what you mean","exaggerating a fact far beyond reality","repeating a word for emphasis","comparing two things with 'comme'"],a:0,ex:"Irony (antiphrase) says the opposite of what is meant: 'Bravo !' after a blunder."},{q:"'C'était vraiment brillant.' said after a failure uses:",opts:["hyperbole","understatement","verbal irony","a simile"],a:2,ex:"Praising a failure means the opposite of what is said: sarcastic irony."},{q:"'Quelle coïncidence !' said sarcastically expresses:",opts:["genuine surprise","sarcastic disbelief","a formal conclusion","a rhetorical question"],a:1,ex:"Said sarcastically, it implies the event was no coincidence at all."},{q:"Chimène's 'Va, je ne te hais point' (Corneille), meaning 'I love you', is a classic:",opts:["litote","hyperbole","oxymore","anaphore"],a:0,ex:"A litote says less to mean more: 'je ne te hais point' understates her love."},{q:"Humour in language often depends on:",opts:["correct grammar alone","shared context and timing","careful spelling","the length of sentences"],a:1,ex:"Jokes and irony work only if speaker and listener share references and the timing is right."},{q:"'Quelle bonne idée de partir sans parapluie !' (in the rain) is:",opts:["sincere praise","ironic criticism","a hypothesis","a polite request"],a:1,ex:"Calling a bad decision a 'bonne idée' in the rain is ironic reproach."}],
[{q:"Efficient listening to a dense French lecture means focusing on:",opts:["transcribing everything","keywords and structure","not taking notes","never pausing to think"],a:1,ex:"Tracking key terms and the plan lets you reconstruct the argument afterwards."},{q:"'Par voie de conséquence' means:",opts:["in addition to this","by contrast","consequently","in a broader sense"],a:2,ex:"'Par voie de conséquence' = as a consequence / therefore."},{q:"'Les résultats suggèrent que...' means:",opts:["The results rule out that...","The results suggest that...","The results prove beyond doubt that...","The results are unrelated to..."],a:1,ex:"'Suggérer' is cautious: the results point to something without proving it."},{q:"'Une digression' in a lecture is:",opts:["the main point","an aside","the conclusion","a citation"],a:1,ex:"A digression temporarily leaves the main topic."},{q:"To follow a dense argument, identify the:",opts:["anecdotes and jokes","main thesis and its steps","exact dates mentioned","speaker's personal views"],a:1,ex:"Knowing the thesis and the steps that support it gives you the argument's skeleton."},{q:"Taking notes on a dense lecture for a synthèse, you should:",opts:["copy every sentence verbatim","note only the speaker's name","note only the examples given","note key ideas and their links"],a:3,ex:"A synthèse compares sources, so track main ideas and where they agree or differ."}],
[{q:"'L'état des choses' means:",opts:["the public's view","the state of affairs","the official plan","the legal framework"],a:1,ex:"'L'état des choses' = the current situation, the state of affairs."},{q:"The 'principe de subsidiarité' in political discourse means:",opts:["centralised decision-making","full regional autonomy","decisions at the lowest level","judicial review of laws"],a:2,ex:"Subsidiarity: decisions are taken at the lowest level able to handle them effectively."},{q:"A 'livre blanc' in policy is:",opts:["a blank document","an official policy paper","a confidential report","an informal memo"],a:1,ex:"A livre blanc (white paper) is an official document setting out policy proposals."},{q:"'Un projet de loi' is:",opts:["a passed law","a draft bill","a court ruling","a petition"],a:1,ex:"'Un projet de loi' is a bill proposed by the government, not yet passed."},{q:"A policy argument requires:",opts:["strong emotion","evidence and reasoning","catchy slogans","personal anecdotes"],a:1,ex:"Policy arguments persuade through evidence and logical reasoning."},{q:"Most nuanced formulation:",opts:["Il est évident que cette loi est un échec complet.","Cette loi, franchement, c'est n'importe quoi, voilà.","Il semblerait que cette loi présente certaines limites.","Tout le monde sait que cette loi ne sert à rien."],a:2,ex:"The conditional 'il semblerait' and 'certaines limites' hedge the criticism."}],
[{q:"'Sérendipité' in French is best:",opts:["translated word for word","kept as a borrowing","replaced by 'bonheur'","avoided entirely"],a:1,ex:"'Sérendipité' is an accepted French borrowing for a happy accidental discovery."},{q:"'Traduire' differs from 'interpréter' in:",opts:["language pair","written vs. spoken","formality","technical vocabulary"],a:1,ex:"In translation studies, 'traduire' is written and 'interpréter' is oral."},{q:"In translation theory, the 'skopos' defines:",opts:["the source text's style","the target text's purpose","the translator's credentials","the payment terms"],a:1,ex:"Skopos theory says the purpose and audience of the target text guide translation choices."},{q:"'Dépaysement' is best rendered in English by:",opts:["a single exact English word","a paraphrase fitted to context","the word 'fear'","the word 'boredom'"],a:1,ex:"'Dépaysement' (the disorientation of being somewhere new) has no one-word English equivalent."},{q:"A faithful translation preserves:",opts:["the exact word order","meaning, tone and intent","the original length","every literal image"],a:1,ex:"Fidelity is to sense and effect, not to the surface form of the source."},{q:"Best French for 'To some extent, both authors agree':",opts:["À une extension, les deux auteurs agréent.","Dans une certaine mesure, les deux auteurs se rejoignent.","Pour quelque extent, les auteurs sont d'accord ensemble.","Les deux auteurs agréent à un degré."],a:1,ex:"'Dans une certaine mesure' = to some extent; 'se rejoindre' = to agree; 'agréer' is a false friend."}],
[{q:"'Conserver le registre du texte' in editing means:",opts:["keeping the same register","raising the register","simplifying the register","mixing several registers"],a:0,ex:"'Conserver' = to keep; the register and tone must stay consistent."},{q:"In a masterclass critique, you address:",opts:["structure, argument and style","spelling and punctuation only","the weaknesses, never strengths","word choice and length only"],a:0,ex:"A full critique covers the whole text: how it is built, argued and written."},{q:"'Métatextuel' refers to:",opts:["text that comments on text","text that is very long","text set in footnotes","text with a hidden code"],a:0,ex:"Metatextual remarks talk about the text itself: 'Dans cette partie, nous verrons...'."},{q:"A masterclass editor balances:",opts:["correction and the author's voice","their own taste and fashion","grammar rules and word count","length and the page layout"],a:0,ex:"Good editing corrects without erasing the author's style."},{q:"The final editing pass focuses on:",opts:["adding new arguments","polishing consistency","restructuring the plan","changing the thesis"],a:1,ex:"The last pass refines details (consistency, nuance); structure is settled earlier."},{q:"A successful final project presentation ends with:",opts:["a new unrelated topic","an apology for the length","a list of grammar mistakes","an answer to the problématique"],a:3,ex:"A French conclusion answers the problématique and often adds an 'ouverture' to a wider question."}]
]
};
